function.arguments:
{"sql": "SELECT e.EntStageName, c.CustLastName
FROM (SELECT EntertainerID, StyleID as first_style, StyleID as second_style FROM (
    SELECT EntertainerID, StyleID as first_style FROM Entertainer_Styles WHERE StyleStrength = 1
) ef
JOIN (SELECT EntertainerID, StyleID as second_style FROM Entertainer_Styles WHERE StyleStrength = 2) es
ON ef.EntertainerID = es.EntertainerID
)) e
JOIN (SELECT CustomerID, StyleID as first_pref, StyleID as second_pref FROM (
    SELECT CustomerID, StyleID as first_pref FROM Musical_Preferences WHERE PreferenceSeq = 1
) cf
JOIN (SELECT CustomerID, StyleID as second_pref FROM Musical_Preferences WHERE PreferenceSeq = 2) cs
ON cf.CustomerID = cs.CustomerID
)) c
JOIN Customers cust ON cust.CustomerID = c.CustomerID
WHERE (c.first_pref = e.first_style AND c.second_pref = e.second_style)
   OR (c.first_pref = e.second_style AND c.second_pref = e.first_style)", "preview_rows": 50}

